class Solution:
    def strStr(self, haystack: str, needle: str) -> int:
        # lps[i]: length of the longest proper prefix of needle[:i+1] that is also its suffix
        lps = [0] * len(needle)
        k = 0
        for i in range(1, len(needle)):
            while k and needle[i] != needle[k]:
                k = lps[k - 1]
            if needle[i] == needle[k]:
                k += 1
            lps[i] = k

        k = 0
        for i, ch in enumerate(haystack):        # the haystack index never moves backwards
            while k and ch != needle[k]:
                k = lps[k - 1]
            if ch == needle[k]:
                k += 1
            if k == len(needle):
                return i - k + 1
        return -1
